static const RFNode* const RF_TREES[RF_N_TREES] = {
  RF_TREE_0,
  RF_TREE_1,
  RF_TREE_2,
  RF_TREE_3,
  RF_TREE_4,
  RF_TREE_5,
  RF_TREE_6,
  RF_TREE_7,
  RF_TREE_8,
  RF_TREE_9,
  RF_TREE_10,
  RF_TREE_11,
  RF_TREE_12,
  RF_TREE_13,
  RF_TREE_14,
  RF_TREE_15,
  RF_TREE_16,
  RF_TREE_17,
  RF_TREE_18,
  RF_TREE_19,
};

static inline float rf_tree_predict(
    const RFNode* nodes,
    const float* x) {
  int16_t idx = 0;
  while (nodes[idx].feature >= 0) {
    const RFNode &n = nodes[idx];
    idx = (x[n.feature] <= n.threshold) ? n.left : n.right;
  }
  return nodes[idx].value;
}

static inline float rf20x7_predict(const float* input) {
  float x[RF_N_FEATURES];
  for (int i = 0; i < RF_N_FEATURES; ++i) {
    x[i] = isfinite(input[i]) ? input[i] : RF_IMPUTER_MEDIANS[i];
  }
  float sum = 0.0f;
  for (int t = 0; t < RF_N_TREES; ++t) {
    sum += rf_tree_predict(RF_TREES[t], x);
  }
  return sum / (float)RF_N_TREES;
}
